-- =====================================================================
-- GesCaisse : catalogue du pressing Hob's-Marie (grille tarifaire) — MySQL (version PHP)
-- 20 articles, chacun avec l'attribut « Prestation » et 4 variantes : Lavage, Express, Repassage,
-- Enfants (prix de la grille, en FCFA). À la caisse, une tuile par article, puis le choix de la
-- prestation. Prestations sans suivi de stock, unité « Pièce », TVA de la société si elle existe.
-- Catégories : Chemises et hauts, Vestes et blousons, Bas, Tenues et costumes, Linge de maison, Accessoires et sous-vêtements.
--
-- 1. Indiquez ci-dessous le CODE de la société (Administration › Sociétés) à la place de LAVERIE, puis exécutez le script
--    sur la base de l'application (phpMyAdmin › Importer, ou onglet SQL).
-- 2. Le script peut être relancé : rien n'est dupliqué et les prix sont remis à ceux de la grille.
-- Codes produits : HM01 à HM20 (modèles), suivis de -01 Lavage, -02 Express, -03 Repassage, -04 Enfants.
-- Généré par Scripts/catalogues/generer_catalogue_hobs_marie.py.
-- =====================================================================

SET NAMES utf8mb4;
SET @t = (SELECT MIN(Id) FROM Tenants WHERE Code = 'LAVERIE');   -- <== code de la société, entre apostrophes
SET @tva = (SELECT MIN(Id) FROM Taxes WHERE TenantId = @t AND Code = 'TVA');
SET @taux = COALESCE((SELECT Taux FROM Taxes WHERE Id = @tva), 0);
SELECT IF(@t IS NULL, 'Société introuvable : indiquez son code en haut du script (à la place de LAVERIE). Rien ne sera modifié.', CONCAT('Société trouvée (Id ', @t, ').')) AS Verification;
START TRANSACTION;

-- Chemises et hauts
INSERT INTO Categories (TenantId, Nom, Couleur, Ordre, Preparation) SELECT @t, 'Chemises et hauts', '#0369a1', 11, 'Aucun' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Categories WHERE TenantId = @t AND Nom = 'Chemises et hauts') AND @t IS NOT NULL;
SET @c = (SELECT MIN(Id) FROM Categories WHERE TenantId = @t AND Nom = 'Chemises et hauts');
INSERT INTO Produits (TenantId, Code, Nom, CategorieId, PrixVente, TauxTVA, SuiviStock, StockActuel, Actif, Unite, EstModele, Supplement, EstCombo)
    SELECT @t, 'HM06', 'Bustier simple', @c, 2500, @taux, 0, 0, 1, 'Pièce', 1, 0, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND @t IS NOT NULL;
UPDATE Produits SET Nom = 'Bustier simple', CategorieId = @c, PrixVente = 2500, EstModele = 1 WHERE TenantId = @t AND Code = 'HM06';
INSERT INTO ProduitAttributs (ProduitId, Nom, Ordre) SELECT Id, 'Prestation', 0 FROM Produits WHERE TenantId = @t AND Code = 'HM06'
    AND NOT EXISTS (SELECT 1 FROM ProduitAttributs pa WHERE pa.ProduitId = Produits.Id AND pa.Nom = 'Prestation');
INSERT INTO ProduitAttributValeurs (ProduitAttributId, Valeur, Ordre) SELECT (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND Nom = 'Prestation'), 'Lavage', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND Nom = 'Prestation') AND Valeur = 'Lavage') AND @t IS NOT NULL;
INSERT INTO Produits (TenantId, Code, Nom, CategorieId, PrixVente, TauxTVA, SuiviStock, StockActuel, Actif, Unite, ParentId, EstModele, Supplement, LibelleVariante, EstCombo)
    SELECT @t, 'HM06-01', 'Bustier simple Lavage', @c, 2500, @taux, 0, 0, 1, 'Pièce', (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06'), 0, 0, 'Lavage', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM06-01') AND @t IS NOT NULL;
UPDATE Produits SET Nom = 'Bustier simple Lavage', CategorieId = @c, PrixVente = 2500, Supplement = 0, LibelleVariante = 'Lavage' WHERE TenantId = @t AND Code = 'HM06-01';
INSERT INTO VarianteValeurs (VarianteId, ValeurId) SELECT v.Id, (SELECT MIN(Id) FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND Nom = 'Prestation') AND Valeur = 'Lavage')
    FROM Produits v WHERE v.TenantId = @t AND v.Code = 'HM06-01' AND NOT EXISTS (SELECT 1 FROM VarianteValeurs x WHERE x.VarianteId = v.Id);
INSERT INTO ProduitAttributValeurs (ProduitAttributId, Valeur, Ordre) SELECT (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND Nom = 'Prestation'), 'Express', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM06') AND Nom = 'Prestation') AND Valeur = 'Express') AND @t IS NOT NULL;
