INSERT INTO VarianteValeurs (VarianteId, ValeurId) SELECT v.Id, (SELECT MIN(Id) FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM10') AND Nom = 'Prestation') AND Valeur = 'Lavage')
    FROM Produits v WHERE v.TenantId = @t AND v.Code = 'HM10-01' AND NOT EXISTS (SELECT 1 FROM VarianteValeurs x WHERE x.VarianteId = v.Id);
INSERT INTO ProduitAttributValeurs (ProduitAttributId, Valeur, Ordre) SELECT (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM10') AND Nom = 'Prestation'), 'Express', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ProduitAttributValeurs WHERE ProduitAttributId = (SELECT MIN(Id) FROM ProduitAttributs WHERE ProduitId = (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM10') AND Nom = 'Prestation') AND Valeur = 'Express') AND @t IS NOT NULL;
