    SELECT @t, 'HM10-02', 'Chaussettes Express', @c, 3000, @taux, 0, 0, 1, 'Pièce', (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM10'), 0, 1500, 'Express', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM10-02') AND @t IS NOT NULL;
UPDATE Produits SET Nom = 'Chaussettes Express', CategorieId = @c, PrixVente = 3000, Supplement = 1500, LibelleVariante = 'Express' WHERE TenantId = @t AND Code = 'HM10-02';
