    SELECT @t, 'HM10-04', 'Chaussettes Enfants', @c, 1000, @taux, 0, 0, 1, 'Pièce', (SELECT Id FROM Produits WHERE TenantId = @t AND Code = 'HM10'), 0, -500, 'Enfants', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM Produits WHERE TenantId = @t AND Code = 'HM10-04') AND @t IS NOT NULL;
